size_t ws_bytes = 0;
cudnnGetConvolutionForwardWorkspaceSize(handle, xDesc, wDesc, convDesc, yDesc,
                                        CUDNN_CONVOLUTION_FWD_ALGO_IMPLICIT_PRECOMP_GEMM,
                                        &ws_bytes);
void *ws = nullptr;
if (ws_bytes > 0) cudaMalloc(&ws, ws_bytes);
cudnnConvolutionForward(handle, alpha, xDesc, x, wDesc, w,
                          convDesc, CUDNN_CONVOLUTION_FWD_ALGO_IMPLICIT_PRECOMP_GEMM,
